-- ZIKR editorial quality remediation
-- Purpose: reduce thin-value article inventory and add substantial, source-linked
-- original educational articles suitable for search discovery and AdSense review.
-- This migration is deliberately conservative: it does not delete data.

begin;

-- Hide previously published articles whose body is too short to function as a
-- useful standalone editorial page. They remain available to editors for revision.
update public.articles
set published = false,
    updated_at = now()
where published = true
  and length(trim(coalesce(content_ar, content, ''))) < 1800;

-- Publish a small library of substantial, original educational articles.
insert into public.articles (
  title, title_ar, title_en, slug,
  content, content_ar, content_en,
  summary, summary_ar, summary_en,
  author, tags, featured, published, views, metadata
)
values
(
  'كيف تبني وردًا قرآنيًا ثابتًا دون أن يتحول إلى عبء؟',
  'كيف تبني وردًا قرآنيًا ثابتًا دون أن يتحول إلى عبء؟',
  'How to Build a Sustainable Quran Reading Routine',
  'build-a-sustainable-quran-reading-routine',
  $content$في هذا الدليل نتعامل مع الورد القرآني باعتباره عادة تحتاج إلى تصميم واقعي، لا سباقًا في عدد الصفحات. كثير من الناس يبدأون بخطة كبيرة ثم يتوقفون عندما يتغير وقت العمل أو الدراسة. البديل الأفضل هو بناء حد أدنى ثابت يمكن المحافظة عليه حتى في الأيام المزدحمة، ثم توسيعه عندما تسمح الظروف.

أول خطوة هي تحديد وقت واضح مرتبط بعادة موجودة أصلًا. يمكن أن يكون الورد بعد صلاة الفجر، أو قبل النوم، أو في فترة هادئة بعد العودة من العمل. المهم أن يكون الموعد قابلًا للتكرار، وأن تكون الأدوات جاهزة مسبقًا: مصحف واحد، أو تطبيق واضح، ومكان مناسب يقلل المشتتات. عندما تصبح البداية سهلة يقل الاحتكاك النفسي الذي يجعل الإنسان يؤجل القراءة.

الخطوة الثانية هي اختيار كمية يمكن الالتزام بها. لا تحتاج الخطة إلى رقم مثالي للجميع. قد يختار شخص عشر دقائق يوميًا، بينما يختار آخر صفحات محددة. الأفضل أن تنجح الخطة في معظم أيام الشهر بدل أن تبدو ممتازة لثلاثة أيام فقط. ويمكن وضع مستوى أساسي صغير للأيام الصعبة ومستوى إضافي للأيام التي يتوفر فيها وقت أطول.

بعد ذلك يأتي جانب الفهم. القراءة لا تعني أن القارئ مطالب بأن يستخرج تفسيرًا من عند نفسه. عند وجود لفظ أو معنى غير واضح، من الأفضل الرجوع إلى تفسير موثوق أو شرح معتمد بدل بناء استنتاج شخصي ثم نسبته إلى الآية. ويمكن للقارئ أن يسجل سؤالًا واحدًا بعد كل جلسة: ما الفكرة التي لفتت انتباهي؟ وما السلوك الذي أحتاج إلى مراجعته؟ بهذه الطريقة يصبح الورد مرتبطًا بالتدبر والعمل من غير ادعاء تفسير متخصص.

ومن المفيد تقسيم الخطة إلى قراءة ومراجعة. القراءة تدفعك إلى الأمام، بينما المراجعة تمنحك فرصة للعودة إلى الآيات التي مررت بها بسرعة. إذا كنت تحفظ القرآن، فالمراجعة تأخذ أولوية واضحة ضمن جدولك. وإذا كان هدفك هو المداومة على التلاوة، فيمكن أن تكون المراجعة أسبوعية عبر اختيار مقطع واحد وإعادة قراءته بهدوء.

أما الهاتف، فهو أداة نافعة لكنه قد يكون أكبر مصدر للتشتت. يمكن تفعيل وضع عدم الإزعاج، وإغلاق الإشعارات، واستخدام صفحة القراءة مباشرة بدل الانتقال بين تطبيقات كثيرة. لا تحتاج إلى جلسة تقنية معقدة؛ الهدف هو تقليل القرارات التي تقع بينك وبين بداية القراءة.

وأخيرًا، راقب الاستمرار بدل عدد الصفحات. سجل عدد الأيام التي التزمت فيها بالخطة، وليس فقط حجم ما قرأته. إذا انخفض الالتزام، لا تعتبر ذلك فشلًا نهائيًا. اسأل لماذا حدث الانقطاع: هل الوقت غير مناسب؟ هل الكمية كبيرة؟ هل المكان مشتت؟ تعديل الخطة بناء على السبب أكثر فائدة من مضاعفة الضغط على نفسك.

هذا المحتوى تعليمي عام وليس فتوى أو تفسيرًا مستقلًا. النص القرآني والموضوعات التعبدية ينبغي الرجوع فيها إلى المصادر الأصلية والتفاسير المعتبرة وأهل الاختصاص عند الحاجة.

المراجع: القرآن الكريم، البقرة 2:185؛ المزمل 73:20؛ الإسراء 17:9؛ Quran.com للتصفح والتحقق.$content$,
