  jsonb_build_object('editorial', true, 'not_fatwa', true, 'source_urls', jsonb_build_array('https://support.google.com/publisherpolicies/answer/11112688'), 'source_note', 'Editorial quality guide for ZIKR; Google guidance is linked for platform-level inventory principles.')
